import AVFoundation

/// Soft start/stop sounds: 10 variants (Resources/sounds/NN-name-start.wav / -stop.wav; generated by scripts/make_sounds.py).
enum Sounds {
    /// id = file prefix; names are localized in L10n.
    static let variants: [(id: String, en: String)] = [
        ("02-pluck", "Pluck"), ("01-classic", "Two notes"), ("03-marimba", "Marimba"), ("04-glass", "Glass"), ("05-wood", "Wood"),
        ("06-chime", "Chime"), ("07-pop", "Pop"), ("08-breath", "Breath"), ("09-bell", "Bell"), ("10-tick", "Tick"),
    ]

    /// Selection value for "no sounds" (also disables the microphone gate).
    static let none = "none"
    static let defaultVariant = "02-pluck"

    private static var cache: [String: AVAudioPlayer] = [:]
    private static func player(_ name: String) -> AVAudioPlayer? {
        if let p = cache[name] { return p }
        let url = Bundle.main.url(forResource: name, withExtension: "wav", subdirectory: "sounds") ?? URL(fileURLWithPath: "Resources/sounds/\(name).wav")
        let p = try? AVAudioPlayer(contentsOf: url)
        p?.volume = 0.6
        p?.prepareToPlay()
        if let p { cache[name] = p }
        return p
    }

    /// Length of the start sound; the recording ignores the microphone this long so the blip is not transcribed.
    static func startDuration(_ v: String) -> Double { player("\(v)-start")?.duration ?? 0.12 }

    static func prepare(_ v: String) { _ = player("\(v)-start"); _ = player("\(v)-stop") }
    static func playStart(_ v: String) { let p = player("\(v)-start"); p?.currentTime = 0; p?.play() }
    static func playStop(_ v: String) { let p = player("\(v)-stop"); p?.currentTime = 0; p?.play() }

    /// Preview in the settings: start, then stop.
    static func preview(_ v: String) {
        guard v != none else { return }
        playStart(v)
        let gap = startDuration(v) + 0.45
        DispatchQueue.main.asyncAfter(deadline: .now() + gap) { playStop(v) }
    }
}
